script='''
const menu=document.querySelector('.menu'),nav=document.querySelector('nav');if(menu)menu.onclick=()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'×':'☰';menu.setAttribute('aria-label',open?'Close navigation':'Open navigation')};nav?.querySelectorAll('a').forEach(a=>{const path=new URL(a.href).pathname;if(!a.classList.contains('btn')&&(path==='/'?location.pathname==='/':location.pathname.startsWith(path)))a.setAttribute('aria-current','page');a.addEventListener('click',()=>{nav.classList.remove('open');menu?.setAttribute('aria-expanded','false');if(menu){menu.textContent='☰';menu.setAttribute('aria-label','Open navigation')}})});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='☰';menu.setAttribute('aria-label','Open navigation');menu.focus()}});document.querySelectorAll('#year').forEach(e=>e.textContent=new Date().getFullYear());
const form=document.getElementById('inquiry');if(form){const interest=new URLSearchParams(location.search).get('interest');const select=form.querySelector('[name=service]');if(interest&&Array.from(select.options).some(o=>o.value===interest))select.value=interest;else if(interest){const message=form.querySelector('[name=message]');message.value='I would like to discuss '+interest.slice(0,120)+'. Project requirements: ';}form.addEventListener('submit',async e=>{e.preventDefault();const status=document.getElementById('notice'),button=form.querySelector('[type=submit]');button.disabled=true;button.textContent='Sending…';status.textContent='';try{const data=Object.fromEntries(new FormData(form));data.consent=Boolean(form.querySelector('[name=consent]').checked);const r=await fetch('/api/inquiries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await r.json();if(!r.ok)throw new Error(result.error||'Your inquiry could not be saved. Please try again.');status.textContent='Thank you. Your inquiry has been saved. Reference: '+result.reference+'. The team can review it in their inbox. A confirmation email has not been sent.';status.focus();form.reset()}catch(error){status.textContent=error.message||'Connection problem. Please try again.';status.focus()}finally{button.disabled=false;button.textContent='Send Inquiry →'}})}
'''
