def polish_body(path,body):
 body=body.replace('Ready-to-use software products','Business software, taking shape.').replace('Four products for everyday operations, currently in development. Request a demo to discuss status and early access.','Four focused products in development for everyday operations. Explore planned features and discuss availability.')
 body=body.replace('Featured projects','Selected project directions').replace('Client project','Project overview')
 if path=='/':
  art=body.find('<div class="hero-art">')
  if art>=0:body=__import__('graphics').replace_div(body,art,studio_visual())
  body=body.replace('</div></div>'+studio_visual(),'</div></div>'+studio_visual()) if False else body
  sections=re.findall(r'<section\b.*?</section>',body,re.S)
  if len(sections)==9:
   body=sections[0]+sections[2]+sections[1]+sections[3]+stack_section()+''.join(sections[4:])
  body=body.replace('Software built to run and grow your business.','Software that moves your business forward.')
  body=body.replace('KS Digital BD builds custom software, websites and apps, and is developing ready-to-use products for retail, pharmacy, restaurants and sales teams.','Websites, mobile apps and custom business systems. Built around your operations, designed for the people who use them.')
  body=body.replace('Explore Our Products','Explore Our Services').replace('href="/products">Explore Our Services','href="/services">Explore Our Services')
 if path=='/services':body=body.replace('<section class="wrap cta">',stack_section()+'<section class="wrap cta">',1)
 if path.startswith('/portfolio/'):
  body=body.replace('Project evidence','About this preview').replace('This overview uses the project information supplied for the website. Screenshots, live links, delivery dates, technical stack and measured results are not published here.','The visual above is an illustrative interface concept. It shows a design direction rather than a live implementation or a verified client result. Contact us to discuss a similar workflow.')
 body=body.replace('People & project credibility','Built on clear expectations').replace('We share team profiles, client references and project evidence when the information is verified and approved for publication. Our portfolio currently provides project overviews without unsupported performance claims.','Every engagement should have a clear brief, an agreed scope and a practical handover plan. We discuss responsibilities, ownership and support before work begins.')
