 if path in ['/', '/services', '/products', '/portfolio', '/industries', '/about']:
  labels={'Software and digital services':'01 / Our expertise','Business software, taking shape.':'02 / Our products','Selected project directions':'03 / Project concepts','Industries we serve':'Built for your world','Why choose KS Digital BD':'A considered partnership','How we work':'From idea to implementation'}
